Step.StepText:
Set Variable [ $resultLog; Value:Let ( [

// ExecuteSQL uses unit/record separators so a value containing a carriage
// return (itemTitles does) cannot be mistaken for a row break. Park any real
// ¶ on Char(11) first, then promote the record separator to ¶ so GetValue can
// walk the rows.
~safe = Substitute ( $raw ; [ ¶ ; Char ( 11 ) ] ; [ Char ( 30 ) ; ¶ ] ) ;
~n    = ValueCount ( ~safe ) ;
~bad  = IsEmpty ( $raw ) or Left ( $raw ; 1 ) = "?"

] ;

"{\"@odata.count\":" & GetAsNumber ( $total ) & ",\"value\":[" &

If ( ~bad ; "" ;
While (
	[ ~i = 1 ; ~out = "" ] ;
	~i ≤ ~n ;
	[ ~c = Substitute ( GetValue ( ~safe ; ~i ) ; Char ( 31 ) ; ¶ ) ;

	  ~num = GetValue ( ~c ; 3 ) ;
	  ~amt = GetValue ( ~c ; 10 ) ;

	  ~o = JSONSetElement ( "{}"
	        ; [ "idText"             ; GetValue ( ~c ; 1 )  ; JSONString ]
	        ; [ "portal"             ; GetValue ( ~c ; 2 )  ; JSONString ]
	        ; [ "status"             ; GetValue ( ~c ; 4 )  ; JSONString ]
	        ; [ "type"               ; GetValue ( ~c ; 5 )  ; JSONString ]
	        ; [ "orderNumber"        ; GetValue ( ~c ; 6 )  ; JSONString ]
	        ; [ "orderDate"          ; GetValue ( ~c ; 7 )  ; JSONString ]
	        ; [ "customerName"       ; GetValue ( ~c ; 8 )  ; JSONString ]
	        ; [ "customerEmail"      ; GetValue ( ~c ; 9 )  ; JSONString ]
	        ; [ "itemCount"          ; GetAsNumber ( GetValue ( ~c ; 11 ) ) ; JSONNumber ]
	        ; [ "itemTitles"         ; Substitute ( GetValue ( ~c ; 12 ) ; Char ( 11 ) ; ¶ ) ; JSONString ]
	        ; [ "zzCreatedTimestamp" ; GetValue ( ~c ; 13 ) ; JSONString ]
	      ) ;

	  ~o = If ( IsEmpty ( ~num ) ;
	            JSONSetElement ( ~o ; "number" ; "null" ; JSONRaw ) ;
	            JSONSetElement ( ~o ; "number" ; ~num ; JSONNumber ) ) ;

	  ~o = If ( IsEmpty ( ~amt ) ;
	            JSONSetElement ( ~o ; "orderAmount" ; "null" ; JSONRaw ) ;
	            JSONSetElement ( ~o ; "orderAmount" ; ~amt ; JSONNumber ) ) ;

	  ~out = ~out & If ( ~i > 1 ; "," ) & ~o ;
	  ~i   = ~i + 1 ] ;
	~out
) )

& "]}" ) ]

